class BBMod:
    def __init__(self):
        self.distName = ""
        self.position = ""
        self.type = ""
        self.number = 0

    def __str__(self):
        return "BBMOD-{} - {} ({})".format(self.number, self.type, self.position)


class CabLink:
    def __init__(self):
        self.bbMod = None
        self.bbModPort = None
        self.radio = None
        self.radioPort = None
        self.chainParent = None
        self.chainParentPort = None
        self.linkSpeed = ""
        self.iqc = None
        self.chainOrdered = False

    def __str__(self):
        if self.chainParent is not None:
            return "{}-{} (p-{})-> {}-{} (p-{})" \
                .format(self.chainParent.name, self.chainParent.number, self.chainParentPort,
                        self.radio.name, self.radio.number, self.radioPort)
        else:
            return "BBMOD-{} (p-{}) -> {}-{} (p-{})" \
                .format(self.bbMod.number, self.bbModPort,
                        self.radio.name, self.radio.number, self.radioPort)


class RadioLink:
    def __init__(self):
        self.number = 0
        self.port = 0
        self.linkSpeed = ""
        self.iqc = None
        self.enbPort = 0
        self.enbBBMod = None
        self.cusPort = 0
        self.cusBBMod = 0
        self.chainParent = None
        self.chainParentPort = 0

    def get_links(self):
        return "X{}.Y{}:{}:{}".format(self.number, self.number, self.port, self.linkSpeed)

    def get_links_comment(self):
        return "X{}.Y{} -> connection to eNB {} - port {}".format(
            self.number, self.number, self.enbBBMod, self.enbPort)

    def get_cloud_links(self):
        if self.chainParent is not None:
            return "CHAINING DETECTED - not supported yet"
        return "{}.{}:{}:{}".format(self.cusBBMod, self.cusPort, self.port, self.linkSpeed)


class RFHead:
    def __init__(self):
        self.links: List[RadioLink] = list()
        self.number = 0
        self.distName = ""
        self.productCode = ""
        self.name = ""
        self.linkType = ""
        self.isCpriA = False

    def __str__(self):
        self.links.sort(key=lambda x: x.port)

        text = "[radio_{}]".format(self.number) + NL
        text += "rmod_type = {}".format(self.name) + NL
        text += "link_type = {}".format(self.linkType) + NL

        if len(self.links) > 0:
            if self.links[0].iqc is not None:
                text += "iqc = {}".format(self.links[0].iqc.replace("bits", "")) + NL

        # Massive MIMO
        if self.name.startswith("AA"):
            text += "af_txul    = 33183" + NL
            text += "af_txulcca = 32234" + NL

        if self.links[0].chainParent is not None:
            text += "parent_radio = {}:{}".format(self.links[0].chainParent.number, self.links[0].chainParentPort)
            text += NL
        else:
            text += "links = "

            # CLOUD CONFIG
            if len(self.links) > 0 and self.links[0].cusPort != 0:
                for _link in self.links:
                    text += _link.get_cloud_links()
                    if self.links.index(_link) != (len(self.links) - 1):
                        text += ", "
                text += NL
            else:
                for _link in self.links:
                    text += _link.get_links()
                    if self.links.index(_link) != (len(self.links) - 1):
                        text += ", "

                text += NL

                for _link in self.links:
                    text += "; " + _link.get_links_comment() + NL

        return text


class Antenna:
    def __init__(self):
        self.rfhead = RFHead()
        self.port = 0
        self.dir = ""

    def __str__(self):
        return "{}:{}:{}".format(self.rfhead.number, self.port, self.dir)


class Cell:
    def __init__(self):
        self.antennas: List[Antenna] = list()
        self.distName = ""
        self.lcrid = 0
        self.number = 0
        self.bw = 0
        self.duplex = ""
        self.earfcn = 0
        self.tac = 0
        self.pci = 0
        self.nbRbDl = 0
        self.nbRbUl = 0
        self.nbRbDlNonAnchor = ""
        self.nbRbUlNonAnchor = ""
        self.nbParent = 0
        self.nbMode = ""
        self.nbChild = None
        self.isLAA = False
        self.laaSCells = list()

    def print(self, p_duplex=False):

        p_bandwidth = self.nbChild
        # print earfcn only for CPRI-A
        p_earfcn = next(filter(lambda x: x.rfhead.isCpriA is True, self.antennas), None)

        if self.nbMode != "":
            ret = "[nb_cell_{}]".format(self.number) + NL
            ret += "type          = {}".format(self.nbMode) + NL
            ret += "parent_sector = {}".format(self.nbParent) + NL
            ret += "dl_rb_res     = {}".format(self.nbRbDl) + NL
            ret += "ul_rb_res     = {}".format(self.nbRbUl) + NL
            if self.nbRbDlNonAnchor:
                ret += "dl_rb_res_non_anchor = {}".format(self.nbRbDlNonAnchor) + NL
            if self.nbRbUlNonAnchor:
                ret += "ul_rb_res_non_anchor = {}".format(self.nbRbUlNonAnchor) + NL
        else:
            self.antennas.sort(key=lambda x: (x.rfhead.number, x.port))
            ret = "[sector_{}]".format(self.number) + NL
            ret += "enb = 1" + NL
            if self.lcrid != self.number:
                ret += "enb_cell_id = {}".format(self.lcrid) + NL

            if p_bandwidth:
                ret += "bandwidth = {}".format(self.bw) + NL

            if p_earfcn:
                ret += "dl_earfcn = {}".format(self.earfcn) + NL

            if p_duplex or self.duplex == "TDD":
                ret += "duplex_mode = {}".format(self.duplex) + NL

            if self.isLAA:
                ret += "ecsat_lte_u = true" + NL

            if len(self.laaSCells):
                ret += "ecsat_lte_u_tx_burst = {}".format(str(self.laaSCells)[1:-1]) + NL
                ret += "ecsat_lte_u_pbch_bcast = {}".format(str(self.laaSCells)[1:-1]) + NL

            ret += "antennas = "
            for _ant in self.antennas:
                ret += "{}".format(_ant)
                if self.antennas.index(_ant) != (len(self.antennas) - 1):
                    ret += ", "

            ret += NL
        return ret


def save_cus_ini(cus_ini_content, file):
    with open(file, "w") as cus_ini_file:
        cus_ini_file.write(cus_ini_content)
    print("Saving new commission in '{}'".format(file))


def set_rrh_name(radio):
    config_path = Path(os.path.abspath(__file__)).parents[1] / 'config'

    iphy_db_path = config_path / 'iphy_db.xml'
    if not path.exists(iphy_db_path):
        iphy_db_path = "src/iphy_db.xml"
        if not path.exists(iphy_db_path):
            raise Exception("Cannot find iphy_db.xml")

    opencpri_path = config_path / 'opencpri_db.xml'
    if not path.exists(opencpri_path):
        opencpri_path = "src/opencpri_db.xml"
        if not path.exists(opencpri_path):
            raise Exception("Cannot find opencpri_db.xml")

    rrh_list = open_xml(iphy_db_path)
    for rrh in rrh_list.findall("RRH"):
        product_code = rrh.find("productcode").text
        product_name = rrh.find("productname").text

        if product_code in radio.productCode:
            radio.name = product_name
            is_obsai = rrh.find("obsai").text
            is_cpri = rrh.find("cpri").text
            # prefer CPRI
            if is_cpri == "true":
                radio.linkType = "CPRI"
            elif is_obsai == "true":
                radio.linkType = "OBSAI"
            return

    cpri_a_rrh_list = open_xml(opencpri_path, False)
    for rrh in cpri_a_rrh_list.findall("RTU"):

        active_sw = rrh.find("ACTIVESW")
        invent_3gpp = rrh.find("INVENT3GPP")
        if active_sw is not None and invent_3gpp is not None:
            card_name = active_sw.find("CARDNAME")
            unit_number = invent_3gpp.find("UNITNUMBER")
            if card_name is not None and unit_number is not None:
                unit_number = unit_number.text

                if unit_number == " " or unit_number == "N":
                    continue

                # also try with last AA characters removed
                unit_number_cut = unit_number[:len(unit_number) - 2]
                if unit_number == radio.productCode or unit_number_cut in radio.productCode:
                    radio.name = card_name.text
                    radio.linkType = "CPRI"
                    radio.isCpriA = True
                    return

    radio.name = "RADIO_NOT_FOUND"


class CusIniCreator:
    def __init__(self):
        self.cellsList: List[Cell] = list()
        self.rfheadsList: List[RFHead] = list()
        self.bbModsList: List[BBMod] = list()
        self.cablinkList: List[CabLink] = list()
        self.commission = None
        self.topology = None
        self.topologyInfo = None
        self.plmn = None

    def get_radios(self):
        for fhs in self.commission.findall(XMLObjectNames.FHS):
            if re.match(r'^d{3}', fhs.find("p[@name='prodCodePlanned']").text):
                rfhead = RFHead()
                rfhead.number = len(self.rfheadsList) + 1
                rfhead.distName = fhs.get("distName")
                rfhead.productCode = fhs.find("p[@name='prodCodePlanned']").text
                set_rrh_name(rfhead)
                self.rfheadsList.append(rfhead)

        for rmod in self.commission.findall(XMLObjectNames.RMOD):
            rfhead = RFHead()
            rfhead.number = len(self.rfheadsList) + 1
            rfhead.distName = rmod.get("distName")
            rfhead.productCode = rmod.find("p[@name='prodCodePlanned']").text
            set_rrh_name(rfhead)
            self.rfheadsList.append(rfhead)

    def get_wb_cells(self):
        for lncel in self.commission.findall(XMLObjectNames.LNCEL):
            cell = Cell()
            cell.distName = lncel.get("distName")
            cell.number = int(cell.distName[cell.distName.find("LNCEL-") + 6:])

            lcrid = lncel.find("p[@name='lcrId']")
            if lcrid is None:
                raise Exception(cell.distName, " -> lcrid is empty")
            cell.lcrid = int(lcrid.text)

            tac = lncel.find("p[@name='tac']")
            if tac is None:
                raise Exception(cell.distName, " -> tac is empty")
            cell.tac = int(tac.text)

            pci = lncel.find("p[@name='phyCellId']")
            if pci is None:
                raise Exception(cell.distName, " -> phyCellId is empty")
            cell.pci = int(pci.text)

            duplex = lncel.find("p[@name='cellTechnology']")
            if duplex is None:
                raise Exception(cell.duplex, " -> cellTechnology is empty")
            cell.duplex = duplex.text

            if cell.duplex == "FDD":
                for lncelFdd in self.commission.findall(XMLObjectNames.LNCEL_FDD):
                    dist_name = lncelFdd.get("distName")
                    if dist_name.find(cell.distName) != -1:
                        bw = lncelFdd.find("p[@name='dlChBw']")
                        if bw is None:
                            raise Exception(dist_name, " -> bw is empty")
                        cell.bw = bw.text.replace(" MHz", "")

                        earfcn = lncelFdd.find("p[@name='earfcnDL']")
                        if earfcn is None:
                            raise Exception(dist_name, " -> earfcnDL is empty")
                        cell.earfcn = int(earfcn.text)

                        break
            elif cell.duplex == "TDD":
                for lncelTdd in self.commission.findall(XMLObjectNames.LNCEL_TDD):
                    dist_name = lncelTdd.get("distName")
                    if dist_name.find(cell.distName) != -1:
                        bw = lncelTdd.find("p[@name='chBw']")
                        if bw is None:
                            raise Exception(dist_name, " -> bw is empty")
                        cell.bw = bw.text.replace(" MHz", "")

                        earfcn = lncelTdd.find("p[@name='earfcn']")
                        if earfcn is None:
                            raise Exception(dist_name, " -> earfcnDL is empty")
                        cell.earfcn = int(earfcn.text)

                        break

            if cell.duplex.find("NB-IoT") != -1:
                continue

            self.cellsList.append(cell)

    def get_nb_cells(self):
        for lncel in self.commission.findall(XMLObjectNames.LNCEL):
            standalone_cell = None

            cell = Cell()
            cell.distName = lncel.get("distName")
            cell.number = int(cell.distName[cell.distName.find("LNCEL-") + 6:])

            lcrid = lncel.find("p[@name='lcrId']")
            if lcrid is None:
                raise Exception(cell.distName, " -> lcrid is empty")
            cell.lcrid = int(lcrid.text)

            tac = lncel.find("p[@name='tac']")
            if tac is None:
                raise Exception(cell.distName, " -> tac is empty")
            cell.tac = int(tac.text)

            pci = lncel.find("p[@name='phyCellId']")
            if pci is None:
                raise Exception(cell.distName, " -> phyCellId is empty")
            cell.pci = int(pci.text)

            duplex = lncel.find("p[@name='cellTechnology']")
            if duplex is None:
                raise Exception(cell.duplex, " -> cellTechnology is empty")
            cell.duplex = duplex.text

            if cell.duplex.find("NB-IoT") == -1:
                continue

            nb_mode = lncel.find("p[@name='nbIoTMode']")
            nbiot = None
            for lncelNB in self.commission.findall(XMLObjectNames.NBIOT_FDD):
                dist_name = lncelNB.get("distName")
                if dist_name.find(cell.distName) != -1:
                    nbiot = lncelNB
                    break

            if nb_mode.text != "standalone":
                parent_id = lncel.find("p[@name='nbIotLinkedCellId']")
                parent_id = int(parent_id.text)
                parent_cell = next(filter(lambda x: x.lcrid == parent_id, self.cellsList), None)
                if parent_cell is not None:
                    cell.nbParent = parent_cell.number
                    parent_cell.nbChild = cell
                cell.number += 100

            if nb_mode.text == "inband":
                cell.nbMode = "IN-BAND"
                rb_dl = nbiot.find("p[@name='inbandPRBIndexDL']")
                cell.nbRbDl = rb_dl.text
                rb_ul = nbiot.find("p[@name='inbandPRBIndexUL']")
                cell.nbRbUl = rb_ul.text

                non_anchor_dl_num = nbiot.find("p[@name='numDlNonAnchCarrierNB']")
                non_anchor_ul_num = nbiot.find("p[@name='numUlNonAnchCarrierNB']")
                if non_anchor_dl_num is not None and non_anchor_dl_num.text != "0":
                    cell.nbRbDlNonAnchor = " <-- put assignedInbandPRBIndexDL for each non anchor ANBIOTCARR"
                if non_anchor_ul_num is not None and non_anchor_ul_num.text != "0":
                    cell.nbRbUlNonAnchor = " <-- put assignedInbandPRBIndexUL for each non anchor ANBIOTCARR"

            elif nb_mode.text == "guardband":
                cell.nbMode = "GUARD-BAND"
                rb_dl = nbiot.find("p[@name='guardbandIndexDL']")
                if rb_dl.text.find("+") != -1:
                    cell.nbRbDl = 0
                else:
                    cell.nbRbDl = -1
                rb_ul = nbiot.find("p[@name='guardbandIndexUL']")
                if rb_ul.text.find("+") != -1:
                    cell.nbRbUl = 0
                else:
                    cell.nbRbUl = -1

                non_anchor_dl_num = nbiot.find("p[@name='numDlNonAnchCarrierNB']")
                non_anchor_ul_num = nbiot.find("p[@name='numUlNonAnchCarrierNB']")
                if non_anchor_dl_num is not None and non_anchor_dl_num.text != "0":
                    non_anchor_dl_num = int(non_anchor_dl_num.text)
                    cell.nbRbDlNonAnchor = NonAnchorGuardBand[cell.nbRbDl][non_anchor_dl_num]

                if non_anchor_ul_num is not None and non_anchor_ul_num.text != "0":
                    non_anchor_ul_num = int(non_anchor_ul_num.text)
                    cell.nbRbUlNonAnchor = NonAnchorGuardBand[cell.nbRbUl][non_anchor_ul_num]

            elif nb_mode.text == "standalone":
                standalone_cell = Cell()
                standalone_cell.distName = lncel.get("distName")
                standalone_cell.number = cell.number + 100
                standalone_cell.nbRbDl = 2
                standalone_cell.nbRbUl = 2
                standalone_cell.nbMode = "STAND-ALONE"
                standalone_cell.nbParent = cell.number
                cell.duplex = "FDD"
                cell.bw = "1.4"
                earfcn = nbiot.find("p[@name='standaloneEarfcnDL']")
                cell.earfcn = earfcn.text
                cell.nbChild = standalone_cell

            self.cellsList.append(cell)
            if standalone_cell is not None:
                self.cellsList.append(standalone_cell)

    def get_cells(self):
        # configuration of NB cells depends on WB cells - so WB first
        self.get_wb_cells()
        self.get_nb_cells()
        self.cellsList.sort(key=lambda c: c.number)

    def get_antennas(self):
        for channel in self.commission.findall(XMLObjectNames.CHANNEL):
            dist_name = channel.get("distName")
            ant_port_id = -1

            # --------------------------------------------------------------------------------
            ant = channel.find("p[@name='antlDN']")
            mmimo_ant = channel.find("p[@name='resourceDN']")

            if ant is None and mmimo_ant is None:
                raise Exception(channel.dist_name, " -> antlDN is empty")

            # regular cell
            if ant is not None:
                ant = ant.text

                antl = self.commission.find("managedObject[@distName='" + ant + "']")
                if antl is None:
                    raise Exception(ant, " -> ant not found")

                ant_port_id = antl.find("p[@name='antPortId']")
                if ant_port_id is None:
                    raise Exception(antl, " -> antPortId not found")
                ant_port_id = int(ant_port_id.text) - 1

                rfhead_dist_name = ant[0: (ant.find("ANTL-") - 1)]

            # Massive MIMO cell
            else:
                mmimo_ant = mmimo_ant.text

                phy_ant = self.commission.find("managedObject[@distName='" + mmimo_ant + "']")
                if phy_ant is None:
                    raise Exception(ant, " -> ant not found")

                ant_port_id = int(dist_name[(dist_name.find("CHANNEL-") + len("CHANNEL-")):])
                if ant_port_id > 4:
                    ant_port_id = ant_port_id - 4

                rfhead_dist_name = mmimo_ant[0: (mmimo_ant.find("PHYANT-") - 1)]

            found_rfhead = next(filter(lambda x: x.distName == rfhead_dist_name, self.rfheadsList), None)

            # --------------------------------------------------------------------------------

            direction = channel.find("p[@name='direction']")
            if direction is None:
                raise Exception(channel.distName, " -> direction is empty")
            direction = "Tx" if direction.text == "TX" else "Rx"

            # --------------------------------------------------------------------------------
            # ignore not LTE cells
            if dist_name.find("LCELL-") == -1:
                continue

            lcell = int(dist_name[dist_name.find("LCELL-") + 6: dist_name.find("CHANNELGROUP-") - 1])

            found_cell = next(filter(lambda x: x.lcrid == lcell, self.cellsList), None)
            if found_cell is None:
                raise Exception(channel.distName, " -> cell not found")

            antenna_exist = next(
                filter(lambda x: x.rfhead == found_rfhead and x.port == ant_port_id, found_cell.antennas),
                None)

            if antenna_exist is None:
                antenna = Antenna()
                antenna.rfhead = found_rfhead
                antenna.port = ant_port_id
                antenna.dir = direction
                found_cell.antennas.append(antenna)

                # check LAA
                if found_rfhead.name.find("AZR") != -1:
                    found_cell.isLAA = True

                    # assumption that first cell is p-cell
                    if self.cellsList[0].laaSCells.count(found_cell.number) == 0:
                        self.cellsList[0].laaSCells.append(found_cell.number)
            else:
                antenna_exist.dir = "TxRx"

    def get_plmn(self):
        lnbts = self.commission.find(XMLObjectNames.LNBTS)
        mcc = lnbts.find("p[@name='mcc']")
        mnc = lnbts.find("p[@name='mnc']")
        mnc_len = lnbts.find("p[@name='mncLength']")

        if mcc is None:
            raise Exception("mcc not found")
        if mnc is None:
            raise Exception("mnc not found")
        if mnc_len is None:
            raise Exception("mncLength not found")

        self.plmn = "{}:{}".format(mcc.text, mnc.text.rjust(int(mnc_len.text), '0'))

    def get_bb_mods(self):
        self.get_plmn()
        for cablink in self.commission.findall(XMLObjectNames.CABLINK):
            smod_port = cablink.find("p[@name='firstEndpointPortId']")
            bbmod_name = cablink.find("p[@name='secondEndpointDN']")

            # skip internal enb connection
            if bbmod_name.text.find("BBMOD") == -1:
                continue

            if bbmod_name is not None:
                number = int(bbmod_name.text[bbmod_name.text.find("BBMOD-") + 6:])
            else:
                number = 0

            if smod_port is not None:
                port = int(smod_port.text)
            else:
                port = 0

            if port == 1 or port == 4:
                position = "Bottom"
            elif port == 2 or port == 5:
                position = "Middle"
            elif port == 3 or port == 6:
                position = "Top"
            else:
                position = "Undefined"

            bbmod_obj = self.commission.find("managedObject[@distName='" + bbmod_name.text + "']")
            if bbmod_obj is not None:
                product_code = bbmod_obj.find("p[@name='prodCodePlanned']").text
                if product_code is not None:
                    if product_code.find(".") != -1:
                        product_code = product_code[:product_code.find(".")]

                    try:
                        bbmod_type = BBModTypes(product_code).name
                    except Exception as exception:
                        print(exception)
                        bbmod_type = "Unknown"

                    bbmod = BBMod()
                    bbmod.type = bbmod_type
                    bbmod.number = number
                    bbmod.position = position
                    bbmod.distName = bbmod_name.text
                    self.bbModsList.append(bbmod)

    def find_link_speed_for_rfhead(self, link_speed, found_rfhead):

        rflink_speed = None

        if link_speed == "Auto":
            link_speed = None

        _rfhead = self.commission.find("managedObject[@distName='" + found_rfhead.distName + "']")
        if _rfhead is not None:
            _rfhead_link_speed = _rfhead.find("p[@name='linkSpeed']")
            if _rfhead_link_speed is not None:
                rflink_speed = _rfhead_link_speed.text
                if rflink_speed == "Auto":
                    rflink_speed = None

        if link_speed is not None and rflink_speed is not None and link_speed != rflink_speed:
            print("WARNING! RFHead-{} ({}) linkSpeed ({}) is different that cablink linkSpeed ({})"
                  .format(found_rfhead.number, found_rfhead.name, rflink_speed, link_speed))

        # use rfhead link speed if not defined in cablink or put default
        if link_speed is None:
            if rflink_speed is not None:
                link_speed = rflink_speed
            else:
                if found_rfhead.linkType == "CPRI":
                    link_speed = "Cpri7"
                else:
                    link_speed = "Obsai6Gbps"

        link_speed = LinkSpeedTypes.get(link_speed) if link_speed in LinkSpeedTypes else "auto"

        return link_speed

    def get_all_cablinks(self):
        for cablink_xml in self.commission.findall(XMLObjectNames.CABLINK):
            ep1_name = cablink_xml.find("p[@name='firstEndpointDN']")
            ep1_port = cablink_xml.find("p[@name='firstEndpointPortId']")
            ep2_name = cablink_xml.find("p[@name='secondEndpointDN']")
            ep2_port = cablink_xml.find("p[@name='secondEndpointPortId']")
            link_speed = cablink_xml.find("p[@name='linkSpeed']")
            iqc = cablink_xml.find("p[@name='iqCompression']")

            cablink = CabLink()

            if link_speed is not None:
                cablink.linkSpeed = link_speed.text
            else:
                cablink.linkSpeed = None

            if iqc is not None and iqc.text != "none":
                cablink.iqc = iqc.text

            # shouldn't happen - those fields are mandatory
            if ep1_name is None or ep2_name is None:
                continue

            ep1_name = ep1_name.text
            ep2_name = ep2_name.text

            if ep1_port is not None:
                ep1_port = ep1_port.text

            if ep2_port is not None:
                ep2_port = ep2_port.text

            # chain radios have both endpoint as RMOD-X
            # normal radios have always first endpoint as BBMOD
            # if BBMOD is second endpoint then it is internal connection which should be skipped
            if ep2_name.find("BBMOD") != -1:
                continue

            # radio in chain
            if ep1_name.find("RMOD") != -1 or ep1_name.find("FHS") != -1:
                found_rfhead_parent: RFHead = next(filter(lambda x: x.distName == ep1_name, self.rfheadsList), None)
                found_rfhead: RFHead = next(filter(lambda x: x.distName == ep2_name, self.rfheadsList), None)

                cablink.radio = found_rfhead
                cablink.chainParent = found_rfhead_parent

                cablink.radioPort = ep2_port
                cablink.chainParentPort = ep1_port
                #
            # regular radio connected to BBMOD
            else:
                found_bbmod: BBMod = next(filter(lambda x: x.distName == ep1_name, self.bbModsList), None)
                found_rfhead: RFHead = next(filter(lambda x: x.distName == ep2_name, self.rfheadsList), None)

                cablink.radio = found_rfhead
                cablink.bbMod = found_bbmod

                # rfhead port undefined
                if ep2_port is None:
                    ep2_port = 1
                else:
                    ep2_port = int(ep2_port)

                cablink.radioPort = ep2_port
                cablink.bbModPort = int(ep1_port)
                cablink.chainOrdered = True

            # cablink.chainOrdered = True
            self.cablinkList.append(cablink)

    def sort_cablinks(self, max_iterations):

        if max_iterations <= 0:
            return

        # recursion stop
        not_ordered = next(filter(lambda x: x.chainOrdered is False, self.cablinkList), None)
        if not_ordered is None:
            return

        # chaining could have radios cablinks in reverse order
        for current_cablink in self.cablinkList:

            # skip already ordered
            if current_cablink.chainOrdered:
                continue

            # now there are only chained radios
            # check if parent radio is connected to bbmod

            found = False

            for parentCablink in self.cablinkList:
                if current_cablink.chainParent == parentCablink.radio:

                    if parentCablink.chainOrdered or parentCablink.bbMod is not None:
                        found = True

            # good order
            if found:
                current_cablink.chainOrdered = True
                if current_cablink.radioPort is None:
                    current_cablink.radioPort = 1
                if current_cablink.chainParentPort is None:
                    current_cablink.chainParentPort = 2
                continue

            for parentCablink in self.cablinkList:
                if current_cablink.radio == parentCablink.radio:
                    if parentCablink.chainOrdered or parentCablink.bbMod is not None:
                        found = True

            # reverse order
            if found:
                tmp_radio = current_cablink.radio
                tmp_port = current_cablink.radioPort
                current_cablink.radio = current_cablink.chainParent
                current_cablink.radioPort = current_cablink.chainParentPort
                current_cablink.chainParent = tmp_radio
                current_cablink.chainParentPort = tmp_port

                if current_cablink.radioPort is None:
                    current_cablink.radioPort = 1
                if current_cablink.chainParentPort is None:
                    current_cablink.chainParentPort = 2

                current_cablink.chainOrdered = True

        self.sort_cablinks(max_iterations - 1)

    def get_rfhead_links(self):

        self.get_all_cablinks()
        self.sort_cablinks(10)

        for cablink in self.cablinkList:
            found_rfhead = cablink.radio

            link_speed = self.find_link_speed_for_rfhead(cablink.linkSpeed, found_rfhead)
            cus_link = RadioLink()
            cus_link.port = cablink.radioPort
            cus_link.linkSpeed = link_speed
            cus_link.iqc = cablink.iqc
            cus_link.number = len(found_rfhead.links) + 1

            if cablink.chainParent is not None:
                cus_link.chainParent = cablink.chainParent
                cus_link.chainParentPort = cablink.chainParentPort
            else:
                cus_link.enbBBMod = cablink.bbMod
                cus_link.enbPort = int(cablink.bbModPort)

            found_rfhead.links.append(cus_link)

    def detect_topology(self, arg_topology):
        if arg_topology is not None:
            self.topology = arg_topology

        elif len(self.bbModsList) == 1:
            bbmod = self.bbModsList[0]
            if bbmod.type == "ABIO":
                self.topology = Topologies.CLOUD_R4BO9_CUS
            elif bbmod.type == "ABIN":
                self.topology = Topologies.CLOUD_R4BN9_CUS
            elif bbmod.type == "ABIA":
                self.topology = Topologies.CLOUD_R4A_CUS
            if bbmod.type == "ABIP":
                self.topology = Topologies.CLOUD_R4LP12_CUS
        elif len(self.bbModsList) == 0:
            try:
                current_smod = SMODTypes(get_product_code(get_smod_object(self.commission), "SMOD"))
                if current_smod == SMODTypes.ASOE:
                    self.topology = Topologies.CLOUD_R4E12_CUS
            except Exception as exception:
                print(exception)
                raise Exception("SMOD Name not found")
        else:
            ret = NL + "Detected BBMods:" + NL
            self.bbModsList.sort(key=lambda x: x.number)
            for bbmod in self.bbModsList:
                ret += "{}".format(bbmod) + NL

            ret += NL + "Cloud topology not detected" + NL

        if self.topology:
            ret = "Detected topology: {}".format(self.topology.name)
        else:
            ret = "Cannot detect topology"

        return ret

    def set_links_for_cloud(self):
        if self.topology is None or self.topology not in TopologiesConnection:
            return

        for rfhead in self.rfheadsList:
            for link in rfhead.links:

                enb_connection = "1.{}".format(link.enbPort)
                cus_connection = TopologiesConnection.get(self.topology).get(enb_connection)
                if cus_connection is not None:
                    cus_connection_arr = cus_connection.split(sep=".")
                    if len(cus_connection_arr) == 2:
                        link.cusBBMod = int(cus_connection_arr[0])
                        link.cusPort = int(cus_connection_arr[1])

    def get_sectors_sections(self):
        ret = ""

        if len(self.cellsList) == 0:
            return "CELLS NOT FOUND!!!"

        # check if all sectors have the same duplex, skip nb_cells
        print_duplex = True == (next(filter(
            lambda x: x.nbParent == 0 and x.duplex != self.cellsList[0].duplex, self.cellsList), None))

        for cell in self.cellsList:
            ret += cell.print(p_duplex=print_duplex) + NL
        return ret

    def get_radios_sections(self):
        ret = ""
        for rfhead in self.rfheadsList:
            ret += "{}".format(rfhead) + NL
        return ret

    def get_ctrls_sections(self):
        ret = "[ctrl_1]" + NL
        ret += "sectors = "

        for cell in self.cellsList:

            # skip inband and guardband
            if cell.nbParent == 0:
                ret += "{}".format(cell.number)
                if cell.nbChild is not None:
                    if cell.nbChild.nbMode != "STAND-ALONE":
                        ret += "x2"

                ret += ","

        ret = ret[:-1]

        ret += NL
        ret += "ip_addr = 192.168.200.1" + NL
        ret += "trsw_ip = 10.0.2.2" + NL
        if self.topology is not None:
            if self.topology == Topologies.CLOUD_R4A_CUS:
                ret += "connector = EIF5" + NL
            if self.topology == Topologies.CLOUD_R4E12_CUS:
                ret += "sync_source = PPS" + NL
            else:
                ret += "sync_source = BackplanePPS" + NL
        ret += NL
        return ret

    def get_cus_ini(self):
        delimiter = ";----------------------------------------------------" + NL
        date = datetime.today().strftime('%Y-%m-%d-%H:%M:%S')

        ret = delimiter
        ret += "; {}".format(self.topologyInfo) + NL
        ret += "; cus.ini generated on {}".format(date) + NL
        ret += delimiter + NL
        ret += get_executor_section()
        ret += get_ip_configuration_section()
        ret += delimiter + NL
        ret += get_enb_section()
        ret += self.get_ctrls_sections()
        ret += self.get_sectors_sections()
        ret += delimiter + NL
        ret += self.get_radios_sections()
        ret += delimiter + NL
        ret += get_tgrs_section()
        ret += delimiter + NL

        ret = prettify_cus_ini(ret)
        return ret


def run(debug_args=None):
    if debug_args is not None:
        args_input = debug_args.get("input")
        args_output = debug_args.get("output")
        topology = debug_args.get("topology")
        args_topology = Topologies(topology) if topology is not None else None
        args_coco = debug_args.get("coco")
    else:
        args = get_arguments()
        args_input = args.input
        args_output = args.output
        args_topology = args.topology
        args_coco = None

    creator = CusIniCreator()

    commission_file = args_input
    topology = args_topology

    creator.commission = open_xml(commission_file)
    creator.get_radios()
    creator.get_cells()
    creator.get_bb_mods()
    creator.get_antennas()
    creator.get_rfhead_links()

    creator.topologyInfo = creator.detect_topology(topology)
    creator.set_links_for_cloud()

    if args_coco is None:
        cus_ini_cont = creator.get_cus_ini()
        print(cus_ini_cont)

        if args_output is not None:
            save_cus_ini(cus_ini_cont, args_output)

    else:
        return creator


if __name__ == '__main__':
    run()
